<script>
(function () {
  const daysEl = document.getElementById('days');
  const monthNameEl = document.querySelector('.month-name');
  const confirmBtn = document.getElementById('confirmBtn');

  const today = new Date();
  let year = today.getFullYear();
  let month = today.getMonth();
  const todayDate = today.getDate();

  const monthNames = [
    'يناير','فبراير','مارس','أبريل','مايو','يونيو',
    'يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'
  ];

  function renderCalendar(y, m) {
    const firstDay = new Date(y, m, 1).getDay(); // 0=Sun .. 6=Sat
    const offset = (firstDay + 1) % 7; // week starts Saturday -> Sat=0
    const daysInMonth = new Date(y, m + 1, 0).getDate();
    const daysInPrev = new Date(y, m, 0).getDate();

    let html = '';
    for (let i = 0; i < 42; i++) {
      const idx = i - offset;
      let dayNum, cls = '';
      if (idx >= 0 && idx < daysInMonth) {
        dayNum = idx + 1;
        if (dayNum === todayDate && m === today.getMonth() && y === today.getFullYear()) {
          cls = 'today';
        }
      } else if (idx < 0) {
        dayNum = daysInPrev + idx + 1;
        cls = 'other-month';
      } else {
        dayNum = idx - daysInMonth + 1;
        cls = 'other-month';
      }
      html += '<div class="day ' + cls + '">' + dayNum + '</div>';
    }
    daysEl.innerHTML = html;

    daysEl.querySelectorAll('.day:not(.other-month)').forEach(d => {
      d.addEventListener('click', function () {
        daysEl.querySelectorAll('.day').forEach(x => x.classList.remove('selected'));
        this.classList.add('selected');
        updateConfirm();
      });
    });
  }

  document.querySelectorAll('.nav-btn')[0].addEventListener('click', function () { // next (left in RTL)
    month++;
    if (month > 11) { month = 0; year++; }
    monthNameEl.textContent = monthNames[month] + ' ' + year;
    renderCalendar(year, month);
  });
  document.querySelectorAll('.nav-btn')[1].addEventListener('click', function () { // prev (right in RTL)
    month--;
    if (month < 0) { month = 11; year--; }
    monthNameEl.textContent = monthNames[month] + ' ' + year;
    renderCalendar(year, month);
  });

  document.querySelectorAll('.slot').forEach(s => {
    s.addEventListener('click', function () {
      document.querySelectorAll('.slot').forEach(x => x.classList.remove('selected'));
      this.classList.add('selected');
      updateConfirm();
    });
  });

  function updateConfirm() {
    const hasDate = daysEl.querySelector('.day.selected');
    const hasTime = document.querySelector('.slot.selected');
    confirmBtn.disabled = !(hasDate && hasTime);
  }

  monthNameEl.textContent = monthNames[month] + ' ' + year;
  renderCalendar(year, month);
})();
</script>
